"""Spike 001b (SPIKE-006): @generated marker × `from __future__ import annotations`
compatibility under libcst (D-RIGOR-02 item 8).

Inherits the SPIKE-005 001b marker DESIGN (3-line PEP 263 / PEP 236 block: 2 comment
lines + 1 blank) but inserts it via **libcst `Module.header`** — a sequence of
``cst.EmptyLine`` carrying ``cst.Comment`` — NOT via ``str.replace`` (Anti-Pitfall 6).
This also empirically confirms RESEARCH open question A2 (exact ``Module.header``
semantics: MEDIUM confidence → verified here).

Marker target: the CURRENT v1.2-head hand-written ámbito
``packages/ambito-financiero-client/src/ambito_financiero_client/client.py`` (a clean
production file — passes ruff check / ruff format --check / mypy --strict / ast.parse).
Because the baseline is clean (unlike SPIKE-005's noisy 001a output), the acceptance bar
is the STRICT one: all 4 verification commands exit 0 on the MARKED file. We ALSO record
the baseline exit codes to prove marker-neutrality (zero new diagnostics; line-shift only).

Verification env note: this script is launched under an ephemeral ``uv run --with
'libcst>=1.8.0,<2'`` environment. The 4 verification subprocesses are spawned with a
SANITIZED env (``VIRTUAL_ENV`` + ``UV_*`` removed) so ``uv run`` resolves the WORKSPACE
``.venv`` (which has the workspace packages installed) — otherwise mypy would emit a
spurious ``import-not-found`` for ``ambito_financiero_client`` (the SPIKE-005 001b
spike-location artifact). This is a harness detail, not a marker property.

Run from repo root (ephemeral libcst — D-05, never added to dev deps):

    uv run --with 'libcst>=1.8.0,<2' python \
      .planning/spikes/SPIKE-006-libcst-codegen-tool-choice/001b-ambito-marker-future-compat/experiment.py
"""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

import libcst as cst

# --- paths ----------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parents[4]
SPIKE_DIR = Path(__file__).resolve().parent
SOURCE = REPO_ROOT / "packages/ambito-financiero-client/src/ambito_financiero_client/client.py"
MARKED = SPIKE_DIR / "client_with_marker.py"
BASELINE = SPIKE_DIR / "client_baseline_no_marker.py"
TRANSCRIPTS = SPIKE_DIR / "verification_transcripts.txt"

# --- step 0: preflight ----------------------------------------------------

if not SOURCE.exists():
    sys.stderr.write(f"FATAL: ámbito client.py missing: {SOURCE}\n")
    raise SystemExit(2)

ORIG_TEXT = SOURCE.read_text()

# --- step 1: libcst lossless round-trip check (A2 empirical) --------------
# The v1.3 premise: cst.parse_module(src).code == src byte-for-byte (no ruff post-pass).

module = cst.parse_module(ORIG_TEXT)
lossless = module.code == ORIG_TEXT
if not lossless:
    sys.stderr.write("FATAL: libcst round-trip is NOT lossless on ámbito client.py\n")
    raise SystemExit(3)

# --- step 2: insert @generated marker via Module.header -------------------
# Anti-Pitfall 6: node-level edit, NEVER str.replace. Module.header holds the leading
# EmptyLine/Comment trivia that precedes the module docstring (PEP 263 / PEP 236 permit
# comments before both the docstring and `from __future__ import annotations`).

MARKER: list[cst.EmptyLine] = [
    cst.EmptyLine(
        comment=cst.Comment("# @generated by libcst from aio.py — DO NOT EDIT BY HAND.")
    ),
    cst.EmptyLine(
        comment=cst.Comment("# To modify, edit aio.py and run `make codegen` (Phase 16 setup).")
    ),
    cst.EmptyLine(),
]
marked_module = module.with_changes(header=[*MARKER, *module.header])
MARKED_TEXT = marked_module.code

BASELINE.write_text(ORIG_TEXT)
MARKED.write_text(MARKED_TEXT)

# --- step 3: structural assertions ----------------------------------------
# (a) marker occupies the first two lines; (b) blank third line; (c) the docstring and
# `from __future__ import annotations` are preserved verbatim below the marker.

marked_lines = MARKED_TEXT.splitlines()
assert marked_lines[0] == "# @generated by libcst from aio.py — DO NOT EDIT BY HAND.", (
    f"marker line 1 mismatch: {marked_lines[0]!r}"
)
assert marked_lines[1] == "# To modify, edit aio.py and run `make codegen` (Phase 16 setup).", (
    f"marker line 2 mismatch: {marked_lines[1]!r}"
)
assert marked_lines[2] == "", f"marker line 3 should be blank: {marked_lines[2]!r}"
assert "from __future__ import annotations" in MARKED_TEXT, "future import lost"
# Marker is additive only: the file tail is preserved verbatim below the marker.
assert MARKED_TEXT.endswith(ORIG_TEXT[-200:]), "tail of file altered by marker insertion"
# Line count grows by exactly 3 (2 comments + 1 blank).
assert len(marked_lines) == len(ORIG_TEXT.splitlines()) + 3, "marker added != 3 lines"

# --- step 4: run 4 verification commands (baseline + marked) --------------
# Sanitize env so `uv run` uses the workspace .venv, not the ephemeral --with env.

CLEAN_ENV = {k: v for k, v in os.environ.items() if k != "VIRTUAL_ENV" and not k.startswith("UV_")}


def cmd_set(target: Path) -> list[tuple[str, list[str]]]:
    return [
        ("ruff check", ["uv", "run", "ruff", "check", str(target)]),
        ("ruff format --check", ["uv", "run", "ruff", "format", "--check", str(target)]),
        ("mypy --strict", ["uv", "run", "mypy", "--strict", str(target)]),
        (
            "ast.parse",
            ["uv", "run", "python", "-c", f"import ast; ast.parse(open({str(target)!r}).read())"],
        ),
    ]


def run_cmds(target: Path) -> list[tuple[str, int, str, str]]:
    out: list[tuple[str, int, str, str]] = []
    for label, argv in cmd_set(target):
        proc = subprocess.run(argv, capture_output=True, text=True, cwd=REPO_ROOT, env=CLEAN_ENV)
        out.append((label, proc.returncode, proc.stdout, proc.stderr))
    return out


baseline_results = run_cmds(BASELINE)
marked_results = run_cmds(MARKED)

# --- step 5: write verification_transcripts.txt ---------------------------

with TRANSCRIPTS.open("w") as fh:
    fh.write(
        "# Spike 001b (SPIKE-006) — @generated marker × from __future__ compatibility\n"
        "# Marker inserted via libcst Module.header (EmptyLine/Comment), NOT str.replace.\n"
        "# Target: current v1.2-head ámbito client.py (clean production file).\n"
        "# Acceptance: all 4 commands exit 0 on the MARKED file (strict) AND marker-neutral\n"
        "#   (marked exit code == baseline exit code for each command; zero new diagnostics).\n"
        "# Verification subprocesses use the workspace .venv (VIRTUAL_ENV/UV_* sanitized).\n\n"
    )
    for label, rc, stdout, stderr in marked_results:
        fh.write(f"=== {label} ===\n")
        fh.write(f"exit {rc}\n")
        for blob in (stdout, stderr):
            if blob:
                fh.write(blob if blob.endswith("\n") else blob + "\n")
        fh.write("\n")
    fh.write("# --- Baseline (no marker) results, for delta comparison -----------\n\n")
    for label, rc, stdout, stderr in baseline_results:
        fh.write(f"=== baseline {label} ===\n")
        fh.write(f"exit {rc}\n")
        for blob in (stdout, stderr):
            if blob:
                fh.write(blob if blob.endswith("\n") else blob + "\n")
        fh.write("\n")

# --- step 6: verdict ------------------------------------------------------
# STRICT: every marked command exits 0.  NEUTRAL: marked rc == baseline rc per command.

marked_all_zero = all(rc == 0 for _, rc, _, _ in marked_results)
neutral = all(
    b_rc == m_rc
    for (_, b_rc, _, _), (_, m_rc, _, _) in zip(baseline_results, marked_results, strict=True)
)

print(f"libcst lossless round-trip on client.py: {'PASS' if lossless else 'FAIL'}")
print(f"marker inserted via Module.header (3 lines): PASS")
for (label, m_rc, _, _), (_, b_rc, _, _) in zip(marked_results, baseline_results, strict=True):
    tag = "MARKER-NEUTRAL" if b_rc == m_rc else "MARKER-INTRODUCED"
    print(f"  {label}: marked_rc={m_rc} baseline_rc={b_rc} exit0={'yes' if m_rc == 0 else 'no'} {tag}")
verdict_pass = marked_all_zero and neutral
print(f"SPIKE 001b VERDICT (item 8): {'PASS' if verdict_pass else 'FAIL'}")
print(f"Transcripts written to {TRANSCRIPTS}")

raise SystemExit(0 if verdict_pass else 1)
